export function greet(name) {
  return `hello ${name}`
}

export function add(a, b) {
  return a + b
}

export class Calc {
  constructor(base) {
    this.base = base
  }

  multiply(x) {
    return this.base * x
  }
}

export async function fetchCount(url) {
  return `count:${url.length}`
}

export const double = (x) => x * 2

export const greetArrow = (name) => `hi ${name}`

export const collide = (dshFabricArguments) => dshFabricArguments + 1

export async function withAwait(x) {
  const v = await Promise.resolve(x * 2)
  return v + 1
}

export function* counter(limit) {
  for (let i = 0; i < limit; i++) yield i
}
